"""Terrain-aware convoy community controller generated by GPT 5.6 Terra Spark Ultra.

Authorship: this file, including its strategy and implementation, was entirely
coded by GPT 5.6 Terra Spark Ultra without human guidance. No human-authored
code, strategy choices, or iterative guidance were used.
"""

from __future__ import annotations

from math import atan2, cos, hypot, pi, sin, sqrt

from swarmbench import BaseSwarmController, CircleObstacle, DroneStatus, DroneType


class SwarmController(BaseSwarmController):
    """Send lane-separated convoys forward while FAST drones screen threats."""

    def initialize(self, game_info):
        self.goal = game_info.target_goal
        self.own_goal = game_info.own_goal
        self.obstacles = tuple(game_info.obstacles)
        self.specs = dict(game_info.drone_specs)
        self.width = game_info.arena_width
        self.height = game_info.arena_height
        self.direction = 1.0 if self.goal.center[0] > self.own_goal.center[0] else -1.0
        self.tick = 0
        self.hunter_targets = {}

        initial = tuple(game_info.own_initial_drones)
        ordered = sorted(initial, key=lambda drone: (drone.position[1], drone.id))
        low = self.goal.y_min + 0.65
        high = self.goal.y_max - 0.65
        span = max(1.4, high - low)
        self.goal_lanes = {
            drone.id: low + span * (rank + 0.5) / max(1, len(ordered))
            for rank, drone in enumerate(ordered)
        }

        fast = sorted(
            (drone for drone in initial if drone.drone_type is DroneType.FAST),
            key=lambda drone: (drone.position[1], drone.id),
        )
        slow = sorted(
            (drone for drone in initial if drone.drone_type is DroneType.SLOW),
            key=lambda drone: (drone.position[1], drone.id),
        )
        escort_count = min(len(fast), len(slow), max(4, (len(fast) + 1) // 2))
        if escort_count <= 1:
            indices = range(escort_count)
        else:
            indices = sorted(
                {
                    round(index * (len(fast) - 1) / (escort_count - 1))
                    for index in range(escort_count)
                }
            )
        self.escort_for = {
            fast[index].id: slow[index].id
            for index in indices
            if index < len(fast) and index < len(slow)
        }

    @staticmethod
    def _clamp(value, low, high):
        return min(high, max(low, value))

    @staticmethod
    def _distance(left, right):
        return hypot(left[0] - right[0], left[1] - right[1])

    @staticmethod
    def _segment_distance(start, end, point):
        dx = end[0] - start[0]
        dy = end[1] - start[1]
        length_sq = dx * dx + dy * dy
        if length_sq < 1e-12:
            return hypot(point[0] - start[0], point[1] - start[1]), 0.0
        fraction = ((point[0] - start[0]) * dx + (point[1] - start[1]) * dy) / length_sq
        fraction = max(0.0, min(1.0, fraction))
        closest = (start[0] + fraction * dx, start[1] + fraction * dy)
        return hypot(point[0] - closest[0], point[1] - closest[1]), fraction

    @staticmethod
    def _segment_box_time(start, end, bounds):
        enter, leave = 0.0, 1.0
        for origin, delta, low, high in (
            (start[0], end[0] - start[0], bounds[0], bounds[1]),
            (start[1], end[1] - start[1], bounds[2], bounds[3]),
        ):
            if abs(delta) < 1e-12:
                if origin < low or origin > high:
                    return None
                continue
            first = (low - origin) / delta
            second = (high - origin) / delta
            if first > second:
                first, second = second, first
            enter = max(enter, first)
            leave = min(leave, second)
            if enter > leave:
                return None
        if leave < 0.0 or enter > 1.0:
            return None
        return max(0.0, enter)

    def _line_clear(self, start, end, margin):
        for obstacle in self.obstacles:
            if isinstance(obstacle, CircleObstacle):
                distance, _ = self._segment_distance(start, end, obstacle.center)
                if distance <= obstacle.radius + margin:
                    return False
            else:
                bounds = (
                    obstacle.x_min - margin,
                    obstacle.x_max + margin,
                    obstacle.y_min - margin,
                    obstacle.y_max + margin,
                )
                if self._segment_box_time(start, end, bounds) is not None:
                    return False
        return True

    def _first_blocker(self, start, end, margin):
        blockers = []
        for obstacle in self.obstacles:
            if isinstance(obstacle, CircleObstacle):
                distance, fraction = self._segment_distance(start, end, obstacle.center)
                if distance <= obstacle.radius + margin:
                    blockers.append((fraction, obstacle))
            else:
                bounds = (
                    obstacle.x_min - margin,
                    obstacle.x_max + margin,
                    obstacle.y_min - margin,
                    obstacle.y_max + margin,
                )
                fraction = self._segment_box_time(start, end, bounds)
                if fraction is not None:
                    blockers.append((fraction, obstacle))
        return min(blockers, key=lambda item: item[0])[1] if blockers else None

    def _escape_target(self, start, finish, obstacle, drone_id):
        """Find a short, clear leg when a cluster blocks every corner exit."""
        if isinstance(obstacle, CircleObstacle):
            center = obstacle.center
        else:
            center = (
                (obstacle.x_min + obstacle.x_max) / 2.0,
                (obstacle.y_min + obstacle.y_max) / 2.0,
            )
        heading = atan2(finish[1] - start[1], finish[0] - start[0])
        away = atan2(start[1] - center[1], start[0] - center[0])
        angles = (
            away,
            away - pi / 2,
            away + pi / 2,
            away - pi / 4,
            away + pi / 4,
            heading - pi / 2,
            heading + pi / 2,
            heading - 3 * pi / 4,
            heading + 3 * pi / 4,
        )
        lane = self.goal_lanes.get(drone_id, self.goal.center[1])
        options = []
        for distance in (0.8, 1.5, 2.3):
            for angle in angles:
                candidate = (
                    self._clamp(start[0] + distance * cos(angle), 0.35, self.width - 0.35),
                    self._clamp(start[1] + distance * sin(angle), 0.35, self.height - 0.35),
                )
                # A live drone may legally be between the 0.25 m collision
                # margin and the planner's wider clearance.  Let it turn
                # outward from there rather than declaring every exit blocked.
                if not self._line_clear(start, candidate, 0.25):
                    continue
                cost = self._distance(candidate, finish)
                if not self._line_clear(candidate, finish, 0.55):
                    cost += 0.9
                cost += 0.02 * abs(candidate[1] - lane)
                options.append((cost, candidate[1], candidate))
        # Holding position is safer than issuing a command through a known
        # obstacle; the next control tick will attempt a fresh route.
        return min(options)[2] if options else start

    def _route_target(self, start, finish, drone_id):
        if self._line_clear(start, finish, 0.72):
            return finish

        obstacle = self._first_blocker(start, finish, 0.72)
        if obstacle is None:
            return finish

        clearance = 1.2
        if isinstance(obstacle, CircleObstacle):
            radius = obstacle.radius + clearance
            approach = atan2(start[1] - obstacle.center[1], start[0] - obstacle.center[0])
            candidates = [
                (
                    obstacle.center[0] + radius * cos(approach + offset),
                    obstacle.center[1] + radius * sin(approach + offset),
                )
                for offset in (-3 * pi / 4, -pi / 2, -pi / 4, pi / 4, pi / 2, 3 * pi / 4)
            ]
        else:
            candidates = [
                (obstacle.x_min - clearance, obstacle.y_min - clearance),
                (obstacle.x_min - clearance, obstacle.y_max + clearance),
                (obstacle.x_max + clearance, obstacle.y_min - clearance),
                (obstacle.x_max + clearance, obstacle.y_max + clearance),
            ]

        lane = self.goal_lanes.get(drone_id, self.goal.center[1])
        choices = []
        for candidate in candidates:
            candidate = (
                self._clamp(candidate[0], 0.45, self.width - 0.45),
                self._clamp(candidate[1], 0.45, self.height - 0.45),
            )
            if not self._line_clear(start, candidate, 0.38):
                continue
            cost = self._distance(start, candidate) + self._distance(candidate, finish)
            if not self._line_clear(candidate, finish, 0.38):
                cost += 2.4
            lane_bias = 0.025 * abs(candidate[1] - lane)
            choices.append((cost + lane_bias, candidate[1], candidate))
        return min(choices)[2] if choices else self._escape_target(start, finish, obstacle, drone_id)

    def _obstacle_push(self, position, maximum):
        push_x = push_y = 0.0
        for obstacle in self.obstacles:
            if isinstance(obstacle, CircleObstacle):
                closest = obstacle.center
                radius = obstacle.radius
            else:
                closest = (
                    self._clamp(position[0], obstacle.x_min, obstacle.x_max),
                    self._clamp(position[1], obstacle.y_min, obstacle.y_max),
                )
                radius = 0.0
            dx = position[0] - closest[0]
            dy = position[1] - closest[1]
            distance = hypot(dx, dy)
            surface = distance - radius
            if surface >= 2.5:
                continue
            if distance < 1e-8:
                dx = 0.0
                dy = 1.0 if position[1] <= self.height / 2 else -1.0
                distance = 1.0
            strength = 0.7 * maximum * max(0.0, 2.5 - surface) / 2.5
            push_x += dx / distance * strength
            push_y += dy / distance * strength
        return push_x, push_y

    def _steer(self, drone, finish, pace=1.0):
        spec = self.specs[drone.drone_type]
        target = self._route_target(drone.position, finish, drone.id)
        dx = target[0] - drone.position[0]
        dy = target[1] - drone.position[1]
        distance = hypot(dx, dy)
        if distance < 1e-8:
            desired_x = desired_y = 0.0
        else:
            desired_speed = min(
                spec.max_speed * pace,
                sqrt(2.0 * spec.max_acceleration * distance),
            )
            desired_x = desired_speed * dx / distance
            desired_y = desired_speed * dy / distance

        acceleration_x = 2.65 * (desired_x - drone.velocity[0]) - 0.12 * drone.acceleration[0]
        acceleration_y = 2.65 * (desired_y - drone.velocity[1]) - 0.12 * drone.acceleration[1]
        push_x, push_y = self._obstacle_push(drone.position, spec.max_acceleration)
        acceleration_x += push_x
        acceleration_y += push_y
        if drone.position[1] < 0.7:
            acceleration_y += spec.max_acceleration
        elif drone.position[1] > self.height - 0.7:
            acceleration_y -= spec.max_acceleration

        magnitude = hypot(acceleration_x, acceleration_y)
        if magnitude > spec.max_acceleration:
            scale = spec.max_acceleration / magnitude
            acceleration_x *= scale
            acceleration_y *= scale
        return acceleration_x, acceleration_y

    def _goal_target(self, drone):
        lane = self.goal_lanes.get(drone.id, self.goal.center[1])
        return (
            self.goal.center[0],
            self._clamp(lane, self.goal.y_min + 0.4, self.goal.y_max - 0.4),
        )

    def _intercept_point(self, hunter, enemy):
        speed = self.specs[hunter.drone_type].max_speed
        relative_x = enemy.position[0] - hunter.position[0]
        relative_y = enemy.position[1] - hunter.position[1]
        velocity_x, velocity_y = enemy.velocity
        quadratic = velocity_x * velocity_x + velocity_y * velocity_y - speed * speed
        linear = 2.0 * (relative_x * velocity_x + relative_y * velocity_y)
        constant = relative_x * relative_x + relative_y * relative_y
        time = None
        if abs(quadratic) < 1e-9:
            if linear < -1e-9:
                time = -constant / linear
        else:
            discriminant = linear * linear - 4.0 * quadratic * constant
            if discriminant >= 0.0:
                root = sqrt(discriminant)
                candidates = [
                    candidate
                    for candidate in (
                        (-linear - root) / (2.0 * quadratic),
                        (-linear + root) / (2.0 * quadratic),
                    )
                    if candidate >= 0.0
                ]
                if candidates:
                    time = min(candidates)
        if time is None:
            time = hypot(relative_x, relative_y) / max(0.1, speed)
        time = self._clamp(time + 0.18, 0.0, 4.5)
        return (
            self._clamp(
                enemy.position[0] + enemy.velocity[0] * time + 0.25 * enemy.acceleration[0] * time * time,
                0.35,
                self.width - 0.35,
            ),
            self._clamp(
                enemy.position[1] + enemy.velocity[1] * time + 0.25 * enemy.acceleration[1] * time * time,
                0.35,
                self.height - 0.35,
            ),
        )

    def _assign_hunters(self, hunters, enemies):
        options = []
        for hunter in hunters:
            hunter_speed = self.specs[hunter.drone_type].max_speed
            for enemy in enemies:
                distance = self._distance(hunter.position, enemy.position)
                intercept_time = distance / max(0.1, hunter_speed)
                own_goal_distance = self._distance(enemy.position, self.own_goal.center)
                threshold = 76.0 if enemy.drone_type is DroneType.SLOW else 54.0
                if own_goal_distance > threshold and enemy.drone_type is DroneType.FAST:
                    continue
                value_bonus = 7.5 * self.specs[enemy.drone_type].point_value
                urgency = max(0.0, threshold - own_goal_distance)
                cost = intercept_time - value_bonus - 0.11 * urgency
                options.append((cost, enemy.id, hunter.id))

        assignments = {}
        claimed = set()
        for _, enemy_id, hunter_id in sorted(options):
            if hunter_id not in assignments and enemy_id not in claimed:
                assignments[hunter_id] = enemy_id
                claimed.add(enemy_id)
        return assignments

    def _guard_target(self, guard, escorted, enemies):
        threats = []
        for enemy in enemies:
            escort_distance = self._distance(enemy.position, escorted.position)
            guard_distance = self._distance(enemy.position, guard.position)
            goal_distance = self._distance(enemy.position, self.own_goal.center)
            incoming = self.direction * (enemy.position[0] - escorted.position[0]) > -4.0
            if (incoming and escort_distance < 15.0) or guard_distance < 8.5 or goal_distance < 24.0:
                value = self.specs[enemy.drone_type].point_value
                threats.append((escort_distance - 2.8 * value, enemy.id, enemy))
        if threats:
            return self._intercept_point(guard, min(threats)[2])

        if self.goal.contains(escorted.position):
            return self._goal_target(guard)
        lead = min(8.0, max(2.8, 0.16 * self._distance(escorted.position, self.goal.center)))
        return (
            self._clamp(escorted.position[0] + self.direction * lead, 0.45, self.width - 0.45),
            self._clamp(
                escorted.position[1] + 0.45 * (self.goal_lanes.get(escorted.id, self.goal.center[1]) - escorted.position[1]),
                0.45,
                self.height - 0.45,
            ),
        )

    def step(self, state):
        self.tick += 1
        own = {
            drone.id: drone
            for drone in state.own_drones
            if drone.status is DroneStatus.ACTIVE
        }
        enemies = [
            drone
            for drone in state.opponent_drones
            if drone.status is DroneStatus.ACTIVE
        ]
        enemy_by_id = {drone.id: drone for drone in enemies}
        active_escorts = {
            fast_id: slow_id
            for fast_id, slow_id in self.escort_for.items()
            if fast_id in own and slow_id in own
        }
        hunters = [
            drone
            for drone in own.values()
            if drone.drone_type is DroneType.FAST and drone.id not in active_escorts
        ]
        if self.tick == 1 or self.tick % 4 == 0:
            self.hunter_targets = self._assign_hunters(hunters, enemies)
        else:
            self.hunter_targets = {
                hunter_id: enemy_id
                for hunter_id, enemy_id in self.hunter_targets.items()
                if hunter_id in own and enemy_id in enemy_by_id
            }

        actions = {}
        for drone in own.values():
            if drone.drone_type is DroneType.SLOW:
                actions[drone.id] = self._steer(drone, self._goal_target(drone))
                continue

            escorted_id = active_escorts.get(drone.id)
            escorted = own.get(escorted_id) if escorted_id is not None else None
            if escorted is not None:
                actions[drone.id] = self._steer(drone, self._guard_target(drone, escorted, enemies), 1.04)
                continue

            enemy_id = self.hunter_targets.get(drone.id)
            if enemy_id in enemy_by_id:
                actions[drone.id] = self._steer(drone, self._intercept_point(drone, enemy_by_id[enemy_id]), 1.08)
            else:
                actions[drone.id] = self._steer(drone, self._goal_target(drone), 1.08)
        return actions
